cd /workspace/tmp && cat > render.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1240, height: 1754 }, deviceScaleFactor: 2 });
  await page.goto('file:///workspace/tmp/poster.html');
  await page.waitForTimeout(800);
  await page.screenshot({ path: process.argv[2] || '/workspace/tmp/poster.png' });
  await browser.close();
})();
EOF
(node render.js /workspace/tmp/poster.png 2>&1 || (cd /workspace/tmp && npm ls playwright --prefix $(npm root -g) 2>/dev/null; echo TRY_GLOBAL; NODE_PATH=$(npm root -g) node render.js /workspace/tmp/poster.png)) && python3 -c "from PIL import Image; im=Image.open('/workspace/tmp/poster.png'); print(im.size)"

